//! `Storage::cast` against PyTorch's `x.to(dtype)` for every pair of Volta dtypes
//! (`tests/fixtures/torch/casts.safetensors`, generated by `scripts/torch_ref/gen_fixtures.py`
//! group `casts`). Values are compared exactly: `-0.0` differs from `0.0`, and NaN
//! matches any NaN (payloads are not specified). Also the casts torch leaves undefined,
//! which Volta refuses.

use half::{bf16, f16};
use volta::io::load_safetensors_raw;
use volta::{DType, Storage};

/// Path of the cast fixture.
const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/torch/casts.safetensors"
);

/// Volta's dtype for a fixture name segment (`NAMES` in the generator).
fn dtype_of(name: &str) -> DType {
    match name {
        "f16" => DType::F16,
        "bf16" => DType::BF16,
        "f32" => DType::F32,
        "f64" => DType::F64,
        "i32" => DType::I32,
        "i64" => DType::I64,
        "u8" => DType::U8,
        "bool" => DType::Bool,
        other => panic!("unknown dtype name {other} in the cast fixture"),
    }
}

/// Each element as an exactly comparable string: float bits (so `-0.0` != `0.0`), "nan"
/// for any NaN, and the integer value for integer dtypes.
fn canon(s: &Storage) -> Vec<String> {
    fn float(x: f64) -> String {
        if x.is_nan() {
            "nan".to_string()
        } else {
            format!("{x:e} ({:#018x})", x.to_bits())
        }
    }
    match s.dtype() {
        DType::F16 => s
            .as_host::<f16>()
            .expect("f16")
            .iter()
            .map(|x| float(x.to_f64()))
            .collect(),
        DType::BF16 => s
            .as_host::<bf16>()
            .expect("bf16")
            .iter()
            .map(|x| float(x.to_f64()))
            .collect(),
        DType::F32 => s
            .as_host::<f32>()
            .expect("f32")
            .iter()
            .map(|&x| float(f64::from(x)))
            .collect(),
        DType::F64 => s
            .as_host::<f64>()
            .expect("f64")
            .iter()
            .map(|&x| float(x))
            .collect(),
        DType::I32 => s
            .as_host::<i32>()
            .expect("i32")
            .iter()
            .map(ToString::to_string)
            .collect(),
        DType::I64 => s
            .as_host::<i64>()
            .expect("i64")
            .iter()
            .map(ToString::to_string)
            .collect(),
        DType::U8 => s
            .as_host::<u8>()
            .expect("u8")
            .iter()
            .map(ToString::to_string)
            .collect(),
        DType::Bool => s
            .as_host::<bool>()
            .expect("bool")
            .iter()
            .map(ToString::to_string)
            .collect(),
        other => panic!("canon: unhandled dtype {other}"),
    }
}

/// Every cast in the fixture, collected, so one run lists all disagreements.
#[test]
fn cast_matches_torch_for_every_pair() {
    let entries = load_safetensors_raw(FIXTURE).expect("cast fixture loads");
    let mut checked = 0;
    let mut wrong = Vec::new();
    for (name, expected) in &entries {
        // `cast.<src>.<set>.<dst>`; inputs are `cast.<src>.<set>`.
        let parts: Vec<&str> = name.split('.').collect();
        let [_, src, set, dst] = parts.as_slice() else {
            continue;
        };
        let input = entries
            .get(&format!("cast.{src}.{set}"))
            .unwrap_or_else(|| panic!("no input for {name}"))
            .to_storage()
            .expect("input decodes");
        assert_eq!(input.dtype(), dtype_of(src), "{name}: input dtype");
        let expected = expected.to_storage().expect("output decodes");
        assert_eq!(expected.dtype(), dtype_of(dst), "{name}: fixture dtype");

        let actual = input.cast(dtype_of(dst));
        assert_eq!(actual.dtype(), dtype_of(dst), "{name}: result dtype");
        let (want, got) = (canon(&expected), canon(&actual));
        assert_eq!(want.len(), got.len(), "{name}: length");
        for (i, ((w, g), x)) in want.iter().zip(&got).zip(canon(&input)).enumerate() {
            if w != g {
                wrong.push(format!("{name}[{i}] from {x}: torch {w}, volta {g}"));
            }
        }
        checked += 1;
    }
    // 4 float sources x (5 float/bool + 2 signed + 1 unsigned targets) + 4 int sources x 8.
    assert_eq!(checked, 4 * 8 + 4 * 8, "fixture entries checked");
    assert!(
        wrong.is_empty(),
        "casts differ from torch:\n{}",
        wrong.join("\n")
    );
}

/// NaN to an integer is undefined in torch; Volta refuses it.
#[test]
#[should_panic(expected = "element 1 is NaN, outside i64's range")]
fn nan_to_int_panics() {
    let _ = Storage::from_typed(vec![1.0f32, f32::NAN]).cast(DType::I64);
}

/// Infinity to an integer is undefined in torch; Volta refuses it.
#[test]
#[should_panic(expected = "element 0 is inf, outside i32's range")]
fn inf_to_int_panics() {
    let _ = Storage::from_typed(vec![f64::INFINITY]).cast(DType::I32);
}

/// A negative float to `u8` is undefined in torch; Volta refuses it rather than wrapping.
#[test]
#[should_panic(expected = "element 0 is -1, outside u8's range")]
fn negative_to_u8_panics() {
    let _ = Storage::from_typed(vec![-1.0f32]).cast(DType::U8);
}

/// The range check is on the truncated value: -0.9 truncates to 0, which `u8` holds.
#[test]
fn negative_fraction_to_u8_truncates_to_zero() {
    let s = Storage::from_typed(vec![-0.9f32, 255.9]).cast(DType::U8);
    assert_eq!(s.as_host::<u8>().expect("u8"), &[0, 255]);
}

/// Just past `i32::MAX` is refused; the largest f64 below 2^31 is accepted.
#[test]
fn f64_to_i32_range_edges() {
    let ok = Storage::from_typed(vec![2_147_483_647.9f64, -2_147_483_648.5]).cast(DType::I32);
    assert_eq!(ok.as_host::<i32>().expect("i32"), &[i32::MAX, i32::MIN]);
    let over =
        std::panic::catch_unwind(|| Storage::from_typed(vec![2_147_483_648.0f64]).cast(DType::I32));
    assert!(over.is_err(), "2^31 fits no i32");
}

/// Same dtype shares the buffer instead of copying.
#[test]
fn same_dtype_cast_shares_the_buffer() {
    let s = Storage::from_typed(vec![1i64, 2]);
    assert_eq!(
        s.cast(DType::I64).as_bytes().as_ptr(),
        s.as_bytes().as_ptr()
    );
}
